import asyncio
import json
import os
from typing import Any, AsyncIterable, AsyncIterator, Dict, Optional

import aiohttp


class OpenAIStreamingSTT:
    def __init__(
        self,
        api_key: Optional[str] = None,
        model: str = "gpt-4o-mini-transcribe",
        sample_rate_hz: int = 16000,
        language: Optional[str] = None,
        audio_format: str = "pcm16",
    ) -> None:
        self.api_key = api_key or os.environ["OPENAI_API_KEY"]
        self.model = model
        self.sample_rate_hz = sample_rate_hz
        self.language = language
        self.audio_format = audio_format
        self.url = "https://api.openai.com/v1/realtime?intent=transcription"

    async def transcribe(
        self,
        audio_chunks: AsyncIterable[bytes],
        *,
        session: Optional[aiohttp.ClientSession] = None,
    ) -> AsyncIterator[Dict[str, Any]]:
        owns_session = session is None
        if owns_session:
            session = aiohttp.ClientSession()

        try:
            headers = {
                "Authorization": f"Bearer {self.api_key}",
                "OpenAI-Beta": "realtime=v1",
            }

            async with session.ws_connect(self.url, headers=headers, heartbeat=30) as ws:
                await ws.send_json(
                    {
                        "type": "transcription_session.update",
                        "session": {
                            "input_audio_format": self.audio_format,
                            "input_audio_transcription": {
                                "model": self.model,
                                **({"language": self.language} if self.language else {}),
                            },
                            "turn_detection": {
                                "type": "server_vad",
                                "threshold": 0.5,
                                "prefix_padding_ms": 300,
                                "silence_duration_ms": 500,
                            },
                        },
                    }
                )

                async def sender() -> None:
                    async for chunk in audio_chunks:
                        if not chunk:
                            continue
                        await ws.send_json(
                            {
                                "type": "input_audio_buffer.append",
                                "audio": chunk.hex(),
                            }
                        )
                    await ws.send_json({"type": "input_audio_buffer.commit"})

                send_task = asyncio.create_task(sender())

                try:
                    async for msg in ws:
                        if msg.type == aiohttp.WSMsgType.TEXT:
                            event = json.loads(msg.data)
                            event_type = event.get("type", "")

                            if event_type in {
                                "conversation.item.input_audio_transcription.delta",
                                "conversation.item.input_audio_transcription.completed",
                                "conversation.item.input_audio_transcription.failed",
                                "error",
                            }:
                                yield event

                            if event_type in {
                                "conversation.item.input_audio_transcription.completed",
                                "conversation.item.input_audio_transcription.failed",
                            }:
                                break

                        elif msg.type == aiohttp.WSMsgType.ERROR:
                            raise RuntimeError("WebSocket error from OpenAI Realtime API")
                        elif msg.type in {
                            aiohttp.WSMsgType.CLOSED,
                            aiohttp.WSMsgType.CLOSING,
                        }:
                            break
                finally:
                    await send_task
        finally:
            if owns_session and session is not None:
                await session.close()
